, r as (select c.*, rm_get_page_complete_v2(c.pg,c.t,200)::jsonb j from c)
select pg, rang, etat, href, (j->>'count')::int as produits,
 (select count(*) from jsonb_array_elements(j->'products') p where (p->>'price_ttc')::numeric>0 and (coalesce(p->>'stock_status','')='' or p->>'stock_status' in ('IN_STOCK','LOW_STOCK','PREORDER','En stock','available','Sur commande'))) as vendables,
 (select string_agg(distinct coalesce(p->>'stock_status','∅'),',') from jsonb_array_elements(j->'products') p) as statuts,
 (select count(*) from __sitemap_p_link s where s.map_pg_id=r.pg and s.map_type_id=r.t and s.map_has_item>0) as dans_sitemap_p_link
from r order by pg, rang;
